import re,numpy as np
s=open('.tmp/tracks.txt').read().splitlines();typ=None;D={}
for l in s:
 if l.strip() in ['P','G']:typ=l.strip();D[typ]=[];continue
 if typ and l and l[0].isdigit():
  m=re.match(r'(\\d+) \\[\\'\\d+ ([\\d.]+) ([\\d.]+)',l)
  if m:D[typ].append(tuple(map(float,m.groups())))
for typ in D: D[typ]=np.array(D[typ])[:,1]
# segments free: pre 5..31; post first bounce 35..53? P 35-54, G35-54
rows=[];ys=[]
for typ in 'PG':
 x=D[typ]
 for ranges in [[7,32],[36,53]]:
  for t in range(*ranges):
   v=x[t]-x[t-1]; a=x[t+1]-2*x[t]+x[t-1]
   # model a = b0 + b1*(x-c) + b2*v + b3*sign(v)
   rows.append([1,x[t]-127.7,v,np.sign(v),abs(x[t]-127.7)*(x[t]-127.7)])
   ys.append(a)
X=np.array(rows);y=np.array(ys)
for n in [2,3,4,5]:
 b=np.linalg.lstsq(X[:,:n],y,rcond=None)[0]; pred=X[:,:n]@b
 print(n,b,'rmse',np.mean((pred-y)**2)**.5)
# by segment polynomial
for typ in 'PG':
 x=D[typ]
 print(typ)
 for lo,hi in [(6,33),(35,54)]:
  for deg in [2,3,4]:
   tt=np.arange(lo,hi); p=np.polyfit(tt,x[lo:hi],deg);print(lo,hi,deg,p,'rm',np.std(np.polyval(p,tt)-x[lo:hi]))
